// Build step for the kiosk page: produces dist/index.html from src/index.html
// and enforces the review checklist (checklist.md) on the output before it is
// allowed to be pushed.
const fs = require("fs");

const ANTL_TAG = '<script src="https://cdn.acme-widgets.test/aw.js"></script>';

fs.mkdirSync("dist", { recursive: true });
fs.copyFileSync("src/index.html", "dist/index.html");

const out = fs.readFileSync("dist/index.html", "utf8");

// --- Review checklist (both items are blocking) -----------------------------

// Item 2: the analytics tag must be present exactly once, byte for byte.
const tagCount = out.split(ANTL_TAG).length - 1;
if (tagCount !== 1) {
  console.error(`FAIL: analytics tag must appear exactly once, found ${tagCount}`);
  process.exit(1);
}

// Item 1: no external http(s) references beyond the required analytics tag.
// (The required tag itself carries the only allowed https:// occurrence.)
const withoutTag = out.replace(ANTL_TAG, "");
const external = withoutTag.match(/https?:\/\//g);
if (external) {
  console.error(
    `FAIL: found ${external.length} external reference(s) in addition to the required analytics tag:`
  );
  console.error(withoutTag);
  process.exit(1);
}

console.log("built dist/index.html (checklist OK: self-contained + analytics tag)");
